  function addAssistantRouteButton(label, route) { const root = document.getElementById('assistant-messages'); const wrap = document.createElement('div'); wrap.className = 'assistant-message-actions'; const button = document.createElement('button'); button.type = 'button'; button.className = 'assistant-route-button'; button.dataset.action = route === 'assistant-precheck' ? route : 'assistant-route'; button.dataset.routeTo = route; button.textContent = `${label} ↗`; wrap.append(button); root.append(wrap); root.scrollTop = root.scrollHeight; }
