  function addMessage(message, user) { const root = document.getElementById('assistant-messages'); const row = document.createElement('div'); row.className = `assistant-message-row ${user ? 'user' : 'agent'}`; const content = document.createElement('div'); content.className = 'assistant-message-content'; if (!user) { const avatar = document.createElement('img'); avatar.className = 'assistant-message-avatar'; avatar.src = 'assets/haihe-agent-avatar.jpg'; avatar.alt = ''; const label = document.createElement('small'); label.textContent = '海禾 · 演示助手'; content.append(label); row.append(avatar); } const bubble = document.createElement('div'); bubble.className = 'assistant-message'; bubble.textContent = message; content.append(bubble); row.append(content); if (user) { const avatar = document.createElement('span'); avatar.className = 'assistant-user-avatar'; avatar.setAttribute('aria-label', '我'); avatar.textContent = '我'; row.append(avatar); } root.append(row); root.scrollTop = root.scrollHeight; }
