  function runPrecheck() { const product = productById(document.getElementById('precheck-product')?.value); const market = document.getElementById('precheck-market')?.value || '日本'; const batchId = document.getElementById('precheck-batch')?.value || ''; const batch = batchId ? window.ShanhaiBridge?.getBatch(batchId) : null; const docs = batch?.docs || {}; const items = [['产品与批次身份', batch ? `已关联 ${batch.id}` : '缺少批次关联', '建立或选择可供批次'], ['检测资料', docs.testReport ? '已登记，待复核有效期和适用范围' : '缺失/待确认', '关联本批次检测报告'], ['原产地资料', docs.originCert ? '已登记，待人工复核' : '缺失/待确认', '核对原产地文件'], ['市场标签', docs.marketLabel ? '已登记，待专业复核' : '缺失/待确认', `确认${market}标签语言与样稿`], ['冷链与运输', docs.coldChain ? '已登记，待补温控记录' : product.id === 'yb' ? '预冷与冷链待确认' : '运输条件待供应方确认', '确认交付地点与温控责任']]; const result = document.getElementById('assistant-precheck-result'); if (result) result.innerHTML = `<strong>${esc(product.name)} · ${esc(productInfo(product).productCode)} · ${esc(market)} ${batch ? `· ${esc(batch.id)}` : ''}</strong>${items.map(([label, status, next]) => `<div class="precheck-item"><b>${esc(label)}</b><span>${esc(status)}</span><small>${esc(next)}</small></div>`).join('')}<p>资料清单只汇总演示档案，不代表法规判断或真实性核验。来源和资料更新时间以对应产品/批次档案为准；规则待核实。未核实项目由业务人员或专业机构确认。</p>`; }
