  function agentAddMessage(text, user) { const root = document.getElementById('agent-messages'); if (!root) return; const bubble = document.createElement('div'); bubble.className = `agent-bubble ${user ? 'user' : ''}`; const paragraph = document.createElement('p'); paragraph.textContent = text; bubble.append(paragraph); if (user) { const time = document.createElement('small'); time.textContent = '你 · 刚刚'; bubble.append(time); } else { const row = document.createElement('div'); row.className = 'agent-reply'; const avatar = document.createElement('img'); avatar.src = 'assets/haihe-agent-avatar.jpg'; avatar.alt = ''; const content = document.createElement('div'); content.className = 'agent-reply-content'; const label = document.createElement('small'); label.textContent = '海禾 · 演示助手'; content.append(label, bubble); row.append(avatar, content); root.append(row); root.scrollTop = root.scrollHeight; return; } root.append(bubble); root.scrollTop = root.scrollHeight; }
