  function submitFarmer() { const form = document.getElementById('farmer-form'); if (!form?.reportValidity()) return; const data = new FormData(form); state.farmers.push({ name: data.get('name'), area: data.get('area'), product: data.get('product'), quantity: data.get('quantity'), period: data.get('period'), status: '待合作社确认' }); saveState(); closeModal(); toast('协作农户资料已登记'); render(); }
  function feedbackRecord(data) { const product = products.find(p => p.name === data.get('product')) || products[0]; const facts = productInfo(product); const batch = facts.batchId ? window.ShanhaiBridge?.getBatch(facts.batchId) : null; const record = { id: `FDB-${Date.now()}`, type: 'feedback', product: product.name, productId: facts.productCode, batchId: batch?.id || '', requestId: data.get('requestId') || '', note: data.get('message'), status: '本地待供应方查看', created: new Date().toISOString().slice(0,10) }; state.feedback.unshift({ product: record.product, type: data.get('type'), message: record.note, status: record.status, created: record.created, productId: record.productId, batchId: record.batchId }); if (record.batchId || record.requestId) window.ShanhaiBridge?.link(record); }
  function submitFeedback() { const form = document.getElementById('feedback-form'); if (!form?.reportValidity()) return; const data = new FormData(form); feedbackRecord(data); saveState(); closeModal(); toast('试单反馈已保存并关联产品批次'); render(); }
